INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Simple vs complex capital structure definition
(2, 'Earnings Per Share', 'Under ASC 260, what distinguishes a complex capital structure from a simple capital structure?', '["The entity has potentially dilutive securities outstanding", "The entity reports both basic and diluted earnings per share", "The entity has multiple classes of common stock issued", "The entity has total stockholders'' equity exceeding $50 million"]'::jsonb, 0, 'Under ASC 260-10-15-2, a complex capital structure exists when an entity has outstanding potentially dilutive securities such as stock options, convertible bonds, or warrants that could reduce EPS upon exercise or conversion. A simple capital structure has none of these. Choice C is incorrect because having multiple common stock classes does not alone create a complex structure without dilutive potential.', 'easy', 1),

-- Q2: medium / L2 — RSUs in diluted EPS via treasury stock method
(2, 'Earnings Per Share', 'Brookfield Industries granted 12,000 restricted stock units to employees on January 1, 2025. As of December 31, 2025, unrecognized compensation cost is $180,000. The average market price during 2025 was $60 per share. Using the treasury stock method, how many incremental shares from the RSUs are added to the diluted EPS denominator?', '["12,000 shares", "9,000 shares", "3,000 shares", "6,000 shares"]'::jsonb, 1, 'Under ASC 260-10-45-28A, unvested share-based payment awards use the treasury stock method with unrecognized compensation cost as assumed proceeds. Shares assumed repurchased equal $180,000 / $60 = 3,000. Incremental shares are 12,000 minus 3,000 = 9,000. Choice A (12,000) incorrectly includes all RSUs without deducting shares assumed repurchased under the treasury stock method.', 'medium', 2),

-- Q3: hard / L4 — Two-class method for participating securities
(2, 'Earnings Per Share', 'Glenwood Corp. has 500,000 common shares and 100,000 shares of Series A preferred stock that participates equally with common stock in dividends after receiving its $2 per share annual preference. Net income is $1,800,000. Declared dividends total $200,000 for preferred and $600,000 for common, leaving $1,000,000 undistributed. Evaluate the correct EPS methodology and determine basic EPS for common shareholders.', '["Standard method; basic EPS is $3.20", "Standard method; basic EPS is $3.60", "Two-class method; basic EPS is $2.87", "Two-class method; basic EPS is $3.20"]'::jsonb, 2, 'Under ASC 260-10-45-60A, participating securities require the two-class method. Undistributed earnings ($1,000,000) are allocated proportionally: common receives 500,000/600,000 of undistributed earnings ($833,333). Basic EPS = ($600,000 + $833,333) / 500,000 = $2.87. Choice D ($3.20) incorrectly allocates all undistributed earnings to common without recognizing the preferred stock''s participation rights.', 'hard', 4),

-- Q4: medium / L3 — Mid-year convertible bond partial-year dilution effect
(2, 'Earnings Per Share', 'Carver Industries issues $1,000,000 face value, 8% convertible bonds on July 1, 2025. Each $1,000 bond converts into 40 shares. The tax rate is 25%. Net income is $750,000 with 200,000 weighted-average common shares. Analyze the effect of the convertible bonds on the 2025 diluted EPS numerator and denominator.', '["Add $60,000 to the numerator and 40,000 shares to the denominator", "Add $40,000 to the numerator and 20,000 shares to the denominator", "Add $60,000 to the numerator and 20,000 shares to the denominator", "Add $30,000 to the numerator and 20,000 shares to the denominator"]'::jsonb, 3, 'Under ASC 260-10-45-40, the if-converted method prorates both adjustments for the period outstanding. Six months of interest is $40,000 ($1,000,000 x 8% x 6/12), net of tax $30,000 ($40,000 x 0.75). Converted shares are 40,000 weighted to 20,000 (6/12). Choice A uses full-year interest of $60,000 and full 40,000 shares without prorating for the July 1 issuance.', 'medium', 3),

-- Q5: hard / L4 — Anti-dilution sequencing with multiple securities
(2, 'Earnings Per Share', 'Mercer Holdings has basic EPS of $4.00 (net income $800,000, 200,000 shares). It has three potentially dilutive securities: stock options adding 20,000 incremental shares, 6% convertible bonds adding $22,500 after-tax interest and 15,000 shares ($1.50 per share impact), and convertible preferred adding $30,000 in dividends and 8,000 shares ($3.75 per share impact). After correctly ranking from most to least dilutive, which securities should be included in diluted EPS?', '["Stock options and convertible bonds only; convertible preferred is antidilutive", "All three securities because each per-share impact is below basic EPS of $4.00", "Stock options and convertible preferred only; convertible bonds are antidilutive", "Stock options only; both convertibles are antidilutive"]'::jsonb, 0, 'Under ASC 260-10-45-44, securities must be ranked from most to least dilutive and tested sequentially. Options reduce EPS to $3.64. Bonds ($1.50 per share) further reduce EPS to $3.50. Convertible preferred ($3.75 per share) would increase EPS above $3.50, making it antidilutive despite falling below basic EPS. Choice B incorrectly assumes any security below basic EPS is automatically dilutive regardless of sequencing order.', 'hard', 4),

-- Q6: easy / L1 — Public entity EPS presentation requirement
(2, 'Earnings Per Share', 'Which type of entity is required to present earnings per share on the face of the income statement under U.S. GAAP?', '["All entities with total assets exceeding $10 million", "All entities filing audited financial statements", "All entities with preferred and common stock outstanding", "Public business entities with common stock or potential common stock traded publicly"]'::jsonb, 3, 'Under ASC 260-10-15-2, only public business entities whose common stock or potential common stock is traded in a public market must present EPS on the income statement. Nonpublic entities may voluntarily present EPS but are not required to. Choice B is incorrect because the requirement is tied to public market trading, not merely to having audited financial statements.', 'easy', 1),

-- Q7: medium / L2 — Mandatorily convertible preferred in diluted EPS
(2, 'Earnings Per Share', 'On January 1, 2025, Westlake Inc. issues 10,000 shares of mandatorily convertible preferred stock that automatically converts into 30,000 common shares on January 1, 2028. The preferred stock pays a $4 annual cumulative dividend per share. Westlake has net income of $900,000 and 200,000 weighted-average common shares. What is diluted EPS for 2025?', '["$4.30", "$3.91", "$3.60", "$4.50"]'::jsonb, 1, 'Under ASC 260-10-45-40, mandatorily convertible preferred stock is included in diluted EPS using the if-converted method. The $40,000 preferred dividend (10,000 x $4) is added back to the numerator ($900,000), and 30,000 conversion shares are added to the denominator (230,000). Diluted EPS = $900,000 / 230,000 = $3.91. Choice A ($4.30) is basic EPS and does not reflect the dilutive effect of the mandatory conversion.', 'medium', 2),

-- Q8: medium / L3 — Retroactive adjustment for post-period stock split
(2, 'Earnings Per Share', 'Hawthorne Corp. reports basic EPS of $6.00 for the year ended December 31, 2025, based on 200,000 weighted-average shares. On February 15, 2026, before the financial statements are issued, the board declares a 2-for-1 stock split. How does this event affect EPS in the 2025 financial statements?', '["No adjustment is required because the split occurred after the balance sheet date", "EPS is adjusted only in the footnotes but not on the face of the statement", "Basic EPS is retroactively restated to $3.00 using 400,000 weighted-average shares", "The split is disclosed as a subsequent event with no effect on reported EPS"]'::jsonb, 2, 'Under ASC 260-10-55-12, stock splits occurring after the balance sheet date but before financial statements are issued must be retroactively reflected in all EPS computations. The 2-for-1 split doubles weighted-average shares to 400,000, reducing basic EPS to $3.00. Choice A is incorrect because ASC 260 specifically requires retroactive EPS adjustment for stock distributions before issuance.', 'medium', 3),

-- Q9: medium / L2 — Weighted-average shares with treasury stock repurchase
(2, 'Earnings Per Share', 'Rutherford Inc. has 300,000 common shares outstanding on January 1, 2025. On September 1, Rutherford repurchases 60,000 shares as treasury stock. No other share transactions occur during 2025. What is the weighted-average number of common shares outstanding?', '["240,000", "300,000", "260,000", "280,000"]'::jsonb, 3, 'Under ASC 260-10-45-10, weighted-average shares reflect the time-weighted effect of share changes. Rutherford had 300,000 shares for 8 months (Jan-Aug) and 240,000 for 4 months (Sep-Dec): (300,000 x 8/12) + (240,000 x 4/12) = 280,000. Choice A (240,000) incorrectly uses only the year-end balance without weighting for the time the full 300,000 shares were outstanding.', 'medium', 2),

-- Q10: medium / L2 — Convertible bonds issued mid-year diluted EPS calculation
(2, 'Earnings Per Share', 'Pinnacle Corp. issues $600,000 face value, 8% convertible bonds on April 1, 2025. Each $1,000 bond converts into 30 shares. Net income is $480,000, weighted-average common shares are 120,000, and the tax rate is 25%. What is diluted EPS?', '["$4.00", "$3.80", "$3.61", "$3.93"]'::jsonb, 1, 'Under ASC 260-10-45-40, the if-converted method prorates adjustments from the bond issuance date. Nine months of after-tax interest is $27,000 ($600,000 x 8% x 9/12 x 0.75), and conversion shares are weighted at 13,500 (18,000 x 9/12). Diluted EPS = $507,000 / 133,500 = $3.80. Choice A ($4.00) is basic EPS and ignores the dilutive effect of the convertible bonds entirely.', 'medium', 2),

-- Q11: medium / L2 — Rights issue theoretical ex-rights price
(2, 'Earnings Per Share', 'Dalton Corp. has 400,000 shares outstanding and issues rights to shareholders allowing them to purchase one new share for every four shares held at $20 per share. The fair value of the stock before the rights offering is $32 per share. Under ASC 260, what is the theoretical ex-rights price per share?', '["$20.00", "$26.00", "$29.60", "$32.00"]'::jsonb, 2, 'Under ASC 260-10-55-20, the theoretical ex-rights price equals total market value of existing shares plus rights proceeds divided by total shares after the offering. Total value = (4 x $32) + (1 x $20) = $148 over 5 shares = $29.60. Choice B ($26.00) incorrectly averages only the market price and exercise price without weighting for the ratio of existing to new shares.', 'medium', 2),

-- Q12: easy / L1 — Participating securities definition
(2, 'Earnings Per Share', 'Under ASC 260, what is a participating security in the context of computing earnings per share?', '["A security that may participate in undistributed earnings with common stock", "A security that the holder may convert into common stock at a fixed price", "A security that grants the holder voting rights at shareholder meetings", "A security that pays a fixed dividend regardless of company earnings"]'::jsonb, 0, 'Under ASC 260-10-20, a participating security is one that may share in undistributed earnings with common shareholders, such as certain preferred stock with participation rights. This triggers the two-class method for basic EPS computation. Choice B describes a convertible security, which is a distinct concept from a participating security.', 'easy', 1),

-- Q13: easy / L1 — EPS required for continuing operations and net income
(2, 'Earnings Per Share', 'Under ASC 260, for which income amounts must a public company present per-share figures on the face of the income statement?', '["Income from continuing operations and net income", "Net income only", "Gross profit, operating income, and net income", "Income before tax and net income"]'::jsonb, 0, 'Under ASC 260-10-45-2, an entity must present basic and diluted EPS for income from continuing operations and for net income on the face of the income statement. Per-share amounts for discontinued operations may be presented on the face or in the notes. Choice B is incomplete because it omits the mandatory per-share disclosure for income from continuing operations.', 'easy', 1),

-- Q14: easy / L1 — Definition of antidilutive
(2, 'Earnings Per Share', 'In the context of earnings per share, what does the term antidilutive mean?', '["A security that reduces the number of shares outstanding upon exercise", "A security that has no effect on reported net income", "A security that decreases both the numerator and denominator equally", "A potential common share inclusion that would increase EPS or decrease loss per share"]'::jsonb, 3, 'Under ASC 260-10-20, an antidilutive security is one whose inclusion in the diluted EPS computation would increase EPS or decrease loss per share. Antidilutive securities are excluded from diluted EPS because their inclusion would overstate per-share performance. Choice A is incorrect because antidilution relates to the EPS effect, not the direction of share count changes.', 'easy', 1),

-- Q15: hard / L4 — Loss from continuing operations makes all potential shares antidilutive
(2, 'Earnings Per Share', 'Crestview Corp. reports a loss from continuing operations of $200,000 and income from discontinued operations of $350,000 (net of tax), resulting in net income of $150,000. The company has 100,000 common shares and 10,000 stock options that would add 3,000 incremental shares under the treasury stock method. Evaluate how the stock options should be treated in diluted EPS.', '["Include the options in diluted EPS for both continuing and discontinued operations", "Include the options only in the discontinued operations EPS calculation", "Exclude the options from diluted EPS entirely because continuing operations shows a loss", "Include the options in diluted EPS because overall net income is positive"]'::jsonb, 2, 'Under ASC 260-10-45-19, when a loss from continuing operations exists, all potentially dilutive securities are excluded from diluted EPS regardless of net income. Continuing operations serves as the control number; if options are antidilutive there, they cannot be treated as dilutive for any other EPS figure. Choice D incorrectly uses net income as the control number rather than income from continuing operations.', 'hard', 4),

-- Q16: medium / L3 — Year-end share repurchase effect on current-year EPS
(2, 'Earnings Per Share', 'Fieldstone Corp. has net income of $1,200,000 and 400,000 weighted-average common shares, producing basic EPS of $3.00. The company repurchases 50,000 shares on December 31, 2025. Assuming net income remains unchanged, analyze the effect on the current year''s basic EPS.', '["Basic EPS increases to $3.43 because the denominator decreases to 350,000", "Basic EPS remains $3.00 because the repurchase occurs on the last day of the year", "Basic EPS decreases because the cash outflow reduces retained earnings", "Basic EPS increases to $3.20 because the shares are weighted for half the year"]'::jsonb, 1, 'Under ASC 260-10-45-10, share changes are weighted by the fraction of the year outstanding. A December 31 repurchase removes 50,000 shares for zero additional days in 2025, leaving the weighted-average at 400,000. Current-year basic EPS remains $3.00. Choice A incorrectly assumes the full reduction affects the current-year weighted average rather than future periods.', 'medium', 3),

-- Q17: medium / L3 — Convertible bond coupon rate effect on per-share dilutive impact
(2, 'Earnings Per Share', 'Sterling Industries has basic EPS of $4.50 with two convertible bond issues: Bond A ($500,000 face, 4% coupon, converts into 10,000 shares) and Bond B ($500,000 face, 10% coupon, converts into 10,000 shares). The tax rate is 25%. Analyze which bond has a greater dilutive impact per incremental share.', '["Bond A is more dilutive because its lower coupon produces a smaller per-share impact of $1.50", "Bond B is more dilutive because its higher coupon adds more to the numerator", "Both bonds are equally dilutive because they convert into the same number of shares", "Neither bond is dilutive because both per-share impacts exceed $4.50"]'::jsonb, 0, 'Under ASC 260-10-45-44, the most dilutive security has the lowest per-share impact. Bond A''s after-tax interest per share is $1.50 ($500,000 x 4% x 0.75 / 10,000) versus Bond B''s $3.75 ($500,000 x 10% x 0.75 / 10,000). The lower the per-share adjustment, the more it reduces diluted EPS. Choice B confuses a larger numerator addition with greater dilution.', 'medium', 3),

-- Q18: easy / L2 — Discontinued operations EPS calculation
(2, 'Earnings Per Share', 'Thornton Holdings reports income from continuing operations of $600,000, a loss from discontinued operations of $100,000 (net of tax), and net income of $500,000. Weighted-average common shares are 200,000 with no preferred stock. What is basic EPS for discontinued operations?', '["$2.50", "$3.00", "$(0.50)", "$0.50"]'::jsonb, 2, 'Under ASC 260-10-45-2, EPS for discontinued operations is computed separately as the discontinued operations amount divided by weighted-average shares: $(100,000) / 200,000 = $(0.50). This amount is presented net of tax on a per-share basis. Choice D ($0.50) incorrectly states the amount as positive, failing to reflect that discontinued operations produced a loss.', 'easy', 2),

-- Q19: easy / L1 — ASC 260 codification topic reference
(2, 'Earnings Per Share', 'Under the FASB Accounting Standards Codification, which topic provides the authoritative guidance on earnings per share?', '["ASC 220", "ASC 260", "ASC 320", "ASC 480"]'::jsonb, 1, 'ASC 260, Earnings Per Share, is the authoritative codification topic governing all aspects of basic and diluted EPS computation and presentation for public entities. Choice A (ASC 220) addresses comprehensive income and Choice C (ASC 320) addresses investments in debt securities, neither of which governs EPS calculations.', 'easy', 1),

-- Q20: easy / L1 — Denominator in basic EPS definition
(2, 'Earnings Per Share', 'What is the denominator used to compute basic earnings per share under ASC 260?', '["Total shares issued as of the balance sheet date", "Total shares outstanding at the end of the reporting period", "The number of shares outstanding weighted by average market price", "The weighted-average number of common shares outstanding during the period"]'::jsonb, 3, 'Under ASC 260-10-45-10, the denominator for basic EPS is the weighted-average number of common shares outstanding during the reporting period, adjusted for stock dividends and splits. Choice B is incorrect because a simple end-of-period count ignores the timing of share issuances and repurchases throughout the year.', 'easy', 1),

-- Q21: easy / L1 — Treasury stock method assumption
(2, 'Earnings Per Share', 'Under ASC 260, what does the treasury stock method assume a company does with proceeds from the hypothetical exercise of stock options?', '["Uses the proceeds to repurchase common shares at the average market price", "Uses the proceeds to retire outstanding long-term debt", "Invests the proceeds in U.S. Treasury securities", "Distributes the proceeds as dividends to existing shareholders"]'::jsonb, 0, 'Under ASC 260-10-45-22, the treasury stock method assumes that proceeds from the hypothetical exercise of options are used to repurchase common shares at the average market price during the period. The net incremental shares are added to the denominator. Choice C confuses the method''s name with an assumption about investing in government securities.', 'easy', 1),

-- Q22: medium / L3 — Written put options effect on diluted EPS
(2, 'Earnings Per Share', 'Oakmont Corp. has written put options obligating it to repurchase 15,000 shares at $50 per share if exercised. The average market price during 2025 is $40 per share. Net income is $600,000 and weighted-average shares are 150,000. Analyze how these written put options affect diluted EPS.', '["They are antidilutive because the market price is below the exercise price", "They add 15,000 shares to the denominator for the assumed repurchase", "They reduce the numerator by $150,000 for the assumed settlement cost", "They add 3,750 incremental shares to the denominator, reducing diluted EPS to $3.90"]'::jsonb, 3, 'Under ASC 260-10-45-35, written put options are dilutive when the exercise price exceeds the average market price. Using the reverse treasury stock method, Oakmont assumes issuing 18,750 shares ($750,000 / $40) to fund repurchase of 15,000 shares at $50, producing 3,750 net incremental shares. Diluted EPS = $600,000 / 153,750 = $3.90. Choice A is incorrect because for written puts, dilution occurs when exercise price exceeds market price.', 'medium', 3),

-- Q23: medium / L2 — Unvested restricted stock in diluted EPS
(2, 'Earnings Per Share', 'Meridian Corp. has 150,000 weighted-average common shares, net income of $750,000, and 20,000 unvested restricted shares with unrecognized compensation cost of $400,000. The average market price is $50 per share. What is diluted EPS?', '["$5.00", "$4.41", "$4.63", "$4.17"]'::jsonb, 2, 'Under ASC 260-10-45-28A, unvested restricted shares use the treasury stock method with unrecognized compensation cost as assumed proceeds. Shares repurchased: $400,000 / $50 = 8,000. Incremental shares: 20,000 - 8,000 = 12,000. Diluted EPS = $750,000 / 162,000 = $4.63. Choice A ($5.00) is basic EPS, which excludes the dilutive effect of unvested restricted shares.', 'medium', 2),

-- Q24: hard / L4 — Contingently issuable shares when conditions not met at period end
(2, 'Earnings Per Share', 'Valmont Industries agreed to issue 25,000 additional shares to former owners of an acquired subsidiary if cumulative net income exceeds $5,000,000 within three years. At December 31, 2025 (end of year two), cumulative net income is $3,800,000 and current-year net income is $2,100,000. Evaluate how the contingently issuable shares are treated for basic and diluted EPS.', '["Include in basic EPS because cumulative earnings are trending toward the target", "Exclude from both basic and diluted EPS because cumulative earnings of $3,800,000 do not meet the $5,000,000 target at period end", "Exclude from basic EPS but include 25,000 shares in diluted EPS based on projected earnings trajectory", "Include in diluted EPS weighted for the fraction of the contingency period elapsed"]'::jsonb, 1, 'Under ASC 260-10-45-48 and -52, contingently issuable shares are included in basic EPS only when all conditions are satisfied. For diluted EPS, the test assumes the reporting date is the end of the contingency period. Because cumulative earnings ($3,800,000) fall short of $5,000,000 at December 31, 2025, shares are excluded from both computations. Choice C incorrectly projects future earnings rather than applying the period-end test.', 'hard', 4),

-- Q25: hard / L4 — Contracts settleable in shares or cash
(2, 'Earnings Per Share', 'Lexington Corp. enters a forward contract obligating it to repurchase $600,000 worth of its own stock in six months. The contract may be settled in shares or cash at the company''s election. The average market price is $40 per share and the forward price is $50 per share. Evaluate whether and how this contract affects diluted EPS under ASC 260.', '["The contract adds 3,000 incremental shares to the denominator because share settlement is presumed when dilutive", "The contract has no effect on diluted EPS because the company can elect cash settlement", "The contract reduces the diluted EPS denominator by 12,000 shares", "The contract is reported only as a subsequent event in the footnotes"]'::jsonb, 0, 'Under ASC 260-10-45-45, when a contract may be settled in shares or cash, share settlement is presumed if dilutive. At a forward price of $50 exceeding the $40 market price, Lexington would issue 15,000 shares ($600,000 / $40) to fund repurchase of 12,000 shares ($600,000 / $50), adding 3,000 net incremental shares. Choice B incorrectly assumes cash settlement election eliminates the dilutive effect.', 'hard', 4),

-- Q26: hard / L3 — Year-to-date vs quarterly EPS divergence
(2, 'Earnings Per Share', 'Summit Corp. reports quarterly net income of $300,000 each quarter. Shares outstanding are 100,000 for Q1 and Q2, then 200,000 for Q3 and Q4 after a July 1 issuance of 100,000 shares. The sum of the four quarterly basic EPS figures is $9.00. What is full-year basic EPS, and how does it compare to the sum of quarterly amounts?', '["Full-year EPS is $9.00, which equals the sum of quarterly EPS amounts", "Full-year EPS is $8.00, and the sum must be reconciled to this amount in the footnotes", "Full-year EPS is $9.00 because each quarter is computed independently", "Full-year EPS is $8.00, and the sum of quarterly EPS amounts will not equal annual EPS"]'::jsonb, 3, 'Under ASC 260-10-45-10, annual EPS uses the annual weighted-average shares: (100,000 x 6/12) + (200,000 x 6/12) = 150,000. Annual EPS = $1,200,000 / 150,000 = $8.00. The sum of quarterly EPS ($3.00 + $3.00 + $1.50 + $1.50 = $9.00) differs because quarterly computations use different weighted-average shares. Choice A incorrectly assumes annual EPS equals the sum of quarterly amounts.', 'hard', 3),

-- Q27: medium / L2 — If-converted preferred stock numerator add-back
(2, 'Earnings Per Share', 'Northland Corp. has net income of $1,200,000, 300,000 weighted-average common shares, and 20,000 shares of $50 par, 8% cumulative convertible preferred stock. Each preferred share converts into 3 common shares. Basic EPS is $3.73 after deducting preferred dividends. What amount is added back to the numerator when computing diluted EPS under the if-converted method?', '["$1,200,000", "$80,000", "$40,000", "$120,000"]'::jsonb, 1, 'Under ASC 260-10-45-40, the if-converted method for convertible preferred stock adds back the preferred dividends deducted from basic EPS. Northland''s preferred dividends are $80,000 (20,000 x $50 x 8%), so the diluted EPS numerator becomes $1,200,000. Choice C ($40,000) incorrectly halves the dividend amount, possibly confusing annual and semiannual payment periods.', 'medium', 2),

-- Q28: medium / L3 — Performance-based stock options in diluted EPS
(2, 'Earnings Per Share', 'Crestwood Inc. grants 30,000 performance-based stock options on January 1, 2025, that vest only if revenue exceeds $20 million in 2025. The exercise price is $25 and the average market price is $50. Revenue for 2025 is $22 million. Analyze how these options are treated in the 2025 diluted EPS computation.', '["Exclude entirely because performance conditions introduce uncertainty", "Include 30,000 shares because the performance target was achieved", "Include 15,000 incremental shares because the performance condition is satisfied at period end", "Include 7,500 incremental shares using half the options to reflect vesting probability"]'::jsonb, 2, 'Under ASC 260-10-45-28A and -48, performance-based options are included in diluted EPS if the performance condition is satisfied at the reporting date. Because 2025 revenue ($22 million) exceeds the $20 million target, the options are included using the treasury stock method: 30,000 - (30,000 x $25 / $50) = 15,000 incremental shares. Choice A incorrectly excludes options whose conditions have been met.', 'medium', 3),

-- Q29: medium / L2 — Post-period stock dividend retroactive adjustment
(2, 'Earnings Per Share', 'Elmsford Corp. reports basic EPS of $5.00 for the year ended December 31, 2025, based on net income of $1,000,000 and 200,000 weighted-average shares. On January 20, 2026, before financial statements are issued, the board declares a 25% stock dividend. What basic EPS should be reported in the 2025 financial statements?', '["$4.00", "$5.00", "$4.50", "$3.75"]'::jsonb, 0, 'Under ASC 260-10-55-12, stock dividends declared after the balance sheet date but before financial statements are issued must be retroactively reflected in EPS computations. The 25% stock dividend increases weighted-average shares to 250,000 (200,000 x 1.25), yielding basic EPS of $4.00 ($1,000,000 / 250,000). Choice B ($5.00) incorrectly ignores the retroactive adjustment required for pre-issuance stock dividends.', 'medium', 2),

-- Q30: medium / L3 — Dual presentation requirement for basic and diluted EPS
(2, 'Earnings Per Share', 'Silverline Corp. has a complex capital structure and presents basic EPS of $5.20 and diluted EPS of $4.80 for 2025. The CFO proposes presenting only diluted EPS on the income statement face, with basic EPS disclosed in the footnotes. Analyze whether this presentation complies with ASC 260.', '["It complies because diluted EPS is more informative for investors", "It complies if the footnote disclosure is prominently referenced on the income statement", "It does not comply because the SEC requires three EPS figures on the income statement", "It does not comply because both basic and diluted EPS must be presented with equal prominence on the face of the income statement"]'::jsonb, 3, 'Under ASC 260-10-45-2, an entity with a complex capital structure must present both basic and diluted EPS with equal prominence on the face of the income statement. Footnote-only disclosure of basic EPS violates this requirement. Choice A incorrectly suggests that the perceived informativeness of one metric allows omission of the other from the income statement face.', 'medium', 3)
;

COMMIT;
